            provider: "openai",
            is_configured: true,
            provider_is_configured: true,
            catalog_only: true
          } as any,
          {
            id: "gemma3:1b",
            model: "tldw:gemma3:1b",
            provider: "ollama",
            is_configured: true,
            provider_is_configured: true
          } as any
        ]
      })
    ).toMatchObject({
      status: "blocked",
      missingRequirement: "chat-model",
      reason: "model-unavailable",
      recommendedAction: "open-model-settings"
    })
